import React, { useState, useRef } from 'react';
import axios from 'axios';

const VideoProcessor = ({ colorblindType, mode }) => {
  const [file, setFile] = useState(null);
  const [processing, setProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const fileInputRef = useRef(null);

  const handleFileSelect = (event) => {
    const selectedFile = event.target.files[0];
    if (selectedFile && selectedFile.type.startsWith('video/')) {
      setFile(selectedFile);
      setError(null);
      setProgress(0);
    } else {
      setError('Please select a valid video file');
    }
  };

  const handleDragOver = (event) => {
    event.preventDefault();
    event.stopPropagation();
  };

  const handleDrop = (event) => {
    event.preventDefault();
    event.stopPropagation();
    const droppedFiles = event.dataTransfer.files;
    if (droppedFiles.length > 0) {
      const droppedFile = droppedFiles[0];
      if (droppedFile.type.startsWith('video/')) {
        setFile(droppedFile);
        setError(null);
        setProgress(0);
      } else {
        setError('Please drop a valid video file');
      }
    }
  };

  const processVideo = async () => {
    if (!file) {
      setError('Please select a video file');
      return;
    }

    try {
      setProcessing(true);
      setError(null);
      setProgress(10);

      const formData = new FormData();
      formData.append('video', file);
      formData.append('colorblind_type', colorblindType);
      formData.append('mode', mode);

      const response = await axios.post('http://localhost:5000/api/process-video', formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
        onUploadProgress: (progressEvent) => {
          const percentCompleted = Math.round((progressEvent.loaded * 40) / progressEvent.total) + 10;
          setProgress(Math.min(percentCompleted, 90));
        },
      });

      setProgress(95);

      if (response.data.success) {
        setResult({
          success: true,
          outputFile: response.data.output_file,
          framesProcessed: response.data.frames_processed,
          processingTime: response.data.processing_time,
        });
        setProgress(100);
      } else {
        setError(response.data.error || 'Processing failed');
      }
    } catch (err) {
      setError('Error processing video: ' + err.message);
    } finally {
      setProcessing(false);
    }
  };

  const downloadVideo = () => {
    if (result && result.outputFile) {
      const link = document.createElement('a');
      link.href = `http://localhost:5000/api/download/${result.outputFile}`;
      link.download = result.outputFile;
      link.click();
    }
  };

  return (
    <div className="component-container">
      <h2>Video Processor</h2>

      {error && (
        <div className="error" style={{ marginBottom: '15px', padding: '10px', backgroundColor: '#ffebee', color: '#c62828', borderRadius: '4px' }}>
          {error}
        </div>
      )}

      <div
        className="upload-area"
        onDragOver={handleDragOver}
        onDrop={handleDrop}
        onClick={() => fileInputRef.current?.click()}
        style={{
          textAlign: 'center',
          padding: '40px 20px',
          border: '2px dashed #ccc',
          borderRadius: '8px',
          backgroundColor: '#fafafa',
          cursor: 'pointer',
          transition: 'all 0.3s',
        }}
      >
        <input
          ref={fileInputRef}
          type="file"
          accept="video/*"
          onChange={handleFileSelect}
          style={{ display: 'none' }}
        />
        {!file ? (
          <>
            <p style={{ fontSize: '16px', marginBottom: '10px' }}>Drag and drop your video here</p>
            <p style={{ fontSize: '14px', color: '#666' }}>or click to select a video file</p>
          </>
        ) : (
          <>
            <p style={{ fontSize: '16px' }}>✓ Selected: {file.name}</p>
            <p style={{ fontSize: '12px', color: '#666' }}>Size: {(file.size / 1024 / 1024).toFixed(2)} MB</p>
          </>
        )}
      </div>

      <div style={{ marginTop: '20px', textAlign: 'center' }}>
        <button
          className="button"
          onClick={processVideo}
          disabled={!file || processing}
          style={{
            padding: '10px 20px',
            fontSize: '16px',
            borderRadius: '8px',
            border: 'none',
            backgroundColor: file && !processing ? '#5d35c4' : '#ccc',
            color: '#fff',
            cursor: file && !processing ? 'pointer' : 'not-allowed',
            transition: 'background-color 0.3s',
          }}
        >
          {processing ? `Processing ${progress}%` : 'Process Video (Optimized)'}
        </button>
      </div>

      {processing && (
        <div style={{ marginTop: '20px' }}>
          <div style={{
            width: '100%',
            height: '8px',
            backgroundColor: '#e0e0e0',
            borderRadius: '4px',
            overflow: 'hidden',
          }}>
            <div style={{
              width: `${progress}%`,
              height: '100%',
              backgroundColor: '#5d35c4',
              transition: 'width 0.3s ease',
            }} />
          </div>
          <p style={{ fontSize: '12px', color: '#666', marginTop: '8px' }}>Processing video... {progress}%</p>
        </div>
      )}

      {result && result.success && (
        <div style={{ marginTop: '20px', textAlign: 'center', backgroundColor: '#e8f5e9', padding: '15px', borderRadius: '8px' }}>
          <p style={{ color: '#2e7d32', fontSize: '16px', marginBottom: '10px' }}>
            ✓ Video processed successfully!
          </p>
          <p style={{ fontSize: '13px', color: '#555', marginBottom: '10px' }}>
            Frames: {result.framesProcessed} | Time: {result.processingTime?.toFixed(2) || 'N/A'}s
          </p>
          <button
            className="button"
            onClick={downloadVideo}
            style={{
              padding: '10px 20px',
              fontSize: '16px',
              borderRadius: '8px',
              border: 'none',
              backgroundColor: '#4caf50',
              color: '#fff',
              cursor: 'pointer',
              transition: 'background-color 0.3s',
            }}
          >
            Download Processed Video
          </button>
        </div>
      )}
    </div>
  );
};

export default VideoProcessor;
